position_py = '''from dataclasses import dataclass
from typing import Optional

@dataclass
class Position:
    symbol: str
    quantity: int = 0
    avg_price: float = 0.0
    realized_pnl: float = 0.0
    last_price: Optional[float] = None
    fees: float = 0.0

    @property
    def side(self) -> str:
        if self.quantity > 0: return "LONG"
        if self.quantity < 0: return "SHORT"
        return "FLAT"

    @property
    def unrealized_pnl(self) -> float:
        if self.quantity == 0 or self.last_price is None:
            return 0.0
        if self.quantity > 0:
            return (self.last_price - self.avg_price) * self.quantity
        return (self.avg_price - self.last_price) * abs(self.quantity)

class PositionManager:
    """Maintains position state from executed fills. No broker calls."""
    def __init__(self):
        self.positions = {}

    def apply_fill(self, symbol: str, side: str, quantity: int, price: float, fee: float = 0.0) -> Position:
        if quantity <= 0 or price <= 0:
            raise ValueError("quantity and price must be positive")
        if side not in {"BUY","SELL"}:
            raise ValueError("side must be BUY or SELL")
        p=self.positions.setdefault(symbol, Position(symbol))
        signed=quantity if side=="BUY" else -quantity
        p.fees += fee

        if p.quantity == 0:
            p.quantity=signed
            p.avg_price=price
            return p

        same=(p.quantity>0)==(signed>0)
        if same:
            total=abs(p.quantity)+abs(signed)
            p.avg_price=(abs(p.quantity)*p.avg_price+abs(signed)*price)/total
            p.quantity += signed
            return p

        closing=min(abs(p.quantity), abs(signed))
        pnl=(price-p.avg_price)*closing*(1 if p.quantity>0 else -1)
        p.realized_pnl += pnl-fee
        p.quantity += signed
        if p.quantity==0:
            p.avg_price=0.0
        elif (p.quantity>0)!=(signed>0):
            p.avg_price=price
        return p

    def mark(self, symbol: str, last_price: float) -> Position:
        if last_price <= 0:
            raise ValueError("last_price must be positive")
        if symbol not in self.positions:
            self.positions[symbol]=Position(symbol)
        self.positions[symbol].last_price=last_price
        return self.positions[symbol]

    def get(self, symbol: str) -> Position:
        return self.positions.setdefault(symbol, Position(symbol))
'''

exit_py = '''from dataclasses import dataclass
from typing import Optional

@dataclass(frozen=True)
class ExitPlan:
    symbol: str
    side: str
    entry_price: float
    stop_price: Optional[float] = None
    target_price: Optional[float] = None
    trailing_distance: Optional[float] = None

@dataclass(frozen=True)
class ExitDecision:
    should_exit: bool
    reason: str
    trigger_price: Optional[float]

class ExitManager:
    """Independent exit-condition evaluator. It returns decisions; it does not execute."""
    def evaluate(self, plan: ExitPlan, last_price: float) -> ExitDecision:
        if last_price <= 0:
            return ExitDecision(False,"invalid_price",None)
        if plan.side=="LONG":
            if plan.stop_price is not None and last_price <= plan.stop_price:
                return ExitDecision(True,"STOP_LOSS",last_price)
            if plan.target_price is not None and last_price >= plan.target_price:
                return ExitDecision(True,"TAKE_PROFIT",last_price)
        elif plan.side=="SHORT":
            if plan.stop_price is not None and last_price >= plan.stop_price:
                return ExitDecision(True,"STOP_LOSS",last_price)
            if plan.target_price is not None and last_price <= plan.target_price:
                return ExitDecision(True,"TAKE_PROFIT",last_price)
        else:
            return ExitDecision(False,"invalid_side",None)
        return ExitDecision(False,"HOLD",None)
'''

