script = r'''#!/usr/bin/env python3
"""
Cybernetics Trading Engine — Historical Chunk Audit & Consolidation

Run:
    python cybernetics_chunk_audit.py "D:\path\to\Downloads"

The script scans recursively for chunk ZIPs/directories, records hashes and
metadata, and consolidates readable source/config/status files into one TXT.
It NEVER executes code from the archives and makes no network requests.
"""

from __future__ import annotations

import csv
import hashlib
import re
import sys
import zipfile
from datetime import datetime
from pathlib import Path

TEXT_EXTENSIONS = {
    ".py", ".pyw", ".md", ".txt", ".rst",
    ".toml", ".ini", ".cfg", ".conf",
    ".json", ".yaml", ".yml", ".xml",
    ".sql", ".sh", ".bat", ".ps1",
    ".csv", ".tsv", ".log",
}

SKIP_PARTS = {
    ".git", "__pycache__", ".pytest_cache", "node_modules",
    ".venv", "venv", "build", "dist",
}

MAX_TEXT_BYTES = 2 * 1024 * 1024

CHUNK_RE = re.compile(r"(?i)(?:^|[^a-z0-9])chunk[-_ ]?(\d+)(?:\b|[^a-z0-9]|$)")


def sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        for block in iter(lambda: f.read(1024 * 1024), b""):
            h.update(block)
    return h.hexdigest()


def chunk_number(name: str) -> str:
    m = CHUNK_RE.search(name)
    return m.group(1) if m else ""


def looks_like_chunk(name: str) -> bool:
    n = name.lower()
    return "chunk" in n and (
        bool(CHUNK_RE.search(n))
        or "rebuilt" in n
        or "foundation" in n
    )


def skipped_member(name: str) -> bool:
    parts = Path(name.replace("\\", "/")).parts
    return any(p.lower() in SKIP_PARTS for p in parts)


def probably_text(data: bytes) -> bool:
    if b"\x00" in data:
        return False
    sample = data[:8192]
    weird = sum(1 for b in sample if b < 9 or 13 < b < 32)
    return weird < max(5, len(sample) // 100)


def decode(data: bytes) -> str:
    for enc in ("utf-8-sig", "utf-8", "cp1252", "latin-1"):
        try:
            return data.decode(enc)
        except UnicodeDecodeError:
            pass
    return data.decode("utf-8", errors="replace")


def relevant_zip_members(z: zipfile.ZipFile):
    items = []
    for info in z.infolist():
        if info.is_dir() or skipped_member(info.filename):
            continue
        p = Path(info.filename)
        base = p.name.lower()
        if (
            p.suffix.lower() in TEXT_EXTENSIONS
            or any(k in base for k in (
                "build_status", "readme", "manifest", "requirements",
                "pyproject", "changelog", "status", "notes"
            ))
        ):
            items.append(info)
    return sorted(items, key=lambda x: x.filename.lower())


def natural_key(path: Path):
    n = chunk_number(path.name)
    return (int(n) if n.isdigit() else 999999, path.name.lower())


def main() -> int:
    root = Path(sys.argv[1]).expanduser().resolve() if len(sys.argv) > 1 else Path.cwd().resolve()

    if not root.is_dir():
        print(f"ERROR: folder not found: {root}")
        return 2

    report = root / "cybernetics_chunks_consolidated.txt"
    manifest = root / "cybernetics_chunks_manifest.csv"

    zip_files = sorted(
        {
            p for p in root.rglob("*.zip")
            if p.is_file() and looks_like_chunk(p.name)
        },
        key=natural_key,
    )

    chunk_dirs = sorted(
        {
            p for p in root.rglob("*")
            if p.is_dir()
            and looks_like_chunk(p.name)
            and not any(part.lower() in SKIP_PARTS for part in p.parts)
        },
        key=natural_key,
    )

    rows = []
    text_parts = []

    text_parts.append(
        f"""CYBERNETICS TRADING ENGINE — HISTORICAL CHUNK AUDIT
Generated: {datetime.now().isoformat(timespec="seconds")}
Scan root: {root}

PURPOSE
=======
Audit historical Cybernetics Trading Engine chunks without executing any
archived code. This report is intended to determine the true cumulative
lineage and identify whether any historical chunk actually needs rebuilding.

IMPORTANT
=========
Do NOT assume that a filename means a unique implementation. Compare hashes,
BUILD_STATUS/README baseline statements, tests, fixes, file inventories and
actual contents before deciding to rebuild anything.
"""
    )

    for idx, zpath in enumerate(zip_files, 1):
        rel = zpath.relative_to(root)
        sha = sha256_file(zpath)
        size = zpath.stat().st_size
        cnum = chunk_number(zpath.name)

        try:
            with zipfile.ZipFile(zpath, "r") as z:
                infos = relevant_zip_members(z)
                rows.append({
                    "type": "zip",
                    "chunk_number": cnum,
                    "path": str(rel),
                    "size_bytes": size,
                    "sha256": sha,
                    "member_count": len(z.infolist()),
                    "relevant_text_member_count": len(infos),
                })

                text_parts.append(
                    "\n" + "=" * 100 +
                    f"\nARCHIVE #{idx}: {rel}\n" +
                    "=" * 100 +
                    f"\nCHUNK_NUMBER: {cnum or 'UNKNOWN'}" +
                    f"\nSIZE_BYTES: {size:,}" +
                    f"\nSHA256: {sha}" +
                    f"\nZIP_MEMBER_COUNT: {len(z.infolist())}" +
                    f"\nRELEVANT_TEXT_MEMBER_COUNT: {len(infos)}\n"
                )

                for info in infos:
                    text_parts.append(
                        f"\n### FILE: {info.filename}\n"
                        f"### BYTES: {info.file_size:,}\n"
                    )
                    try:
                        data = z.read(info)
                        if len(data) > MAX_TEXT_BYTES:
                            text_parts.append(
                                f"[TRUNCATED AT {MAX_TEXT_BYTES:,} BYTES]\n"
                            )
                            data = data[:MAX_TEXT_BYTES]
                        if probably_text(data):
                            text_parts.append(decode(data))
                        else:
                            text_parts.append("[BINARY / NON-TEXT CONTENT SKIPPED]\n")
                    except Exception as exc:
                        text_parts.append(
                            f"[READ ERROR: {type(exc).__name__}: {exc}]\n"
                        )

        except zipfile.BadZipFile as exc:
            rows.append({
                "type": "zip",
                "chunk_number": cnum,
                "path": str(rel),
                "size_bytes": size,
                "sha256": sha,
                "member_count": "",
                "relevant_text_member_count": "",
            })
            text_parts.append(
                f"\n{'=' * 100}\nBAD ZIP: {rel}\nSHA256: {sha}\nERROR: {exc}\n"
            )

    for d in chunk_dirs:
        rel_dir = d.relative_to(root)
        text_parts.append(
            f"\n\n{'=' * 100}\nDIRECTORY: {rel_dir}\n{'=' * 100}\n"
        )

        for fp in sorted(d.rglob("*"), key=lambda p: str(p).lower()):
            if not fp.is_file():
                continue
            if any(part.lower() in SKIP_PARTS for part in fp.parts):
                continue
            if fp.suffix.lower() not in TEXT_EXTENSIONS:
                continue

            rel = fp.relative_to(root)
            try:
                size = fp.stat().st_size
                sha = sha256_file(fp)
                data = fp.read_bytes()
                shown = data[:MAX_TEXT_BYTES]
                rows.append({
                    "type": "directory_file",
                    "chunk_number": chunk_number(d.name),
                    "path": str(rel),
                    "size_bytes": size,
                    "sha256": sha,
                    "member_count": "",
                    "relevant_text_member_count": "",
                })
                text_parts.append(
                    f"\n### FILE: {rel}\n"
                    f"### SHA256: {sha}\n"
                )
                if len(data) > MAX_TEXT_BYTES:
                    text_parts.append(
                        f"[TRUNCATED AT {MAX_TEXT_BYTES:,} BYTES]\n"
                    )
                text_parts.append(
                    decode(shown) if probably_text(shown)
                    else "[BINARY / NON-TEXT CONTENT SKIPPED]\n"
                )
            except Exception as exc:
                text_parts.append(
                    f"\n### FILE: {rel}\n"
                    f"[READ ERROR: {type(exc).__name__}: {exc}]\n"
                )

    # Audit summary.
    all_numbers = sorted({
        int(r["chunk_number"])
        for r in rows
        if str(r["chunk_number"]).isdigit()
    })
    gaps = []
    if all_numbers:
        present = set(all_numbers)
        gaps = [n for n in range(min(all_numbers), max(all_numbers) + 1) if n not in present]

    hash_map = {}
    for r in rows:
        if r["sha256"]:
            hash_map.setdefault(r["sha256"], []).append(r["path"])
    exact_dupes = {k: v for k, v in hash_map.items() if len(v) > 1}

    text_parts.append(
        "\n\n" + "=" * 100 +
        "\nAUDIT SUMMARY / DECISION AID\n" +
        "=" * 100 +
        f"\nZIP FILES FOUND: {len(zip_files)}" +
        f"\nCHUNK DIRECTORIES FOUND: {len(chunk_dirs)}" +
        f"\nUNIQUE CHUNK NUMBERS OBSERVED: {len(all_numbers)}"
    )

    if all_numbers:
        text_parts.append(
            f"\nOBSERVED RANGE: {min(all_numbers)}..{max(all_numbers)}"
        )

    text_parts.append(
        f"\nNUMBERING GAPS: {gaps if gaps else 'NONE'}"
        f"\nEXACT SHA256 DUPLICATE GROUPS: {len(exact_dupes)}\n"
    )

    if exact_dupes:
        text_parts.append("\nEXACT DUPLICATE CANDIDATES:\n")
        for sha, paths in exact_dupes.items():
            text_parts.append(f"\nSHA256 {sha}\n")
            text_parts.extend(f"  - {p}\n" for p in paths)

    text_parts.append(
        """
NEXT REVIEW RULE
================
Use this report to decide whether historical chunks are:
  A) already represented by a later cumulative checkpoint,
  B) a correction/rebuild variant of an earlier chunk,
  C) genuinely missing work,
  D) or merely archival duplicates.

The objective is NOT to rebuild 1..127/128 just because they exist.
The objective is to establish the latest trustworthy cumulative checkpoint
and continue forward from that point.

SECURITY
========
No archived code is executed.
No network calls are made.
No files are deleted or modified.
Keep this consolidated TXT private and inspect it for secrets before sharing.
"""
    )

    report.write_text("".join(text_parts), encoding="utf-8")

    with manifest.open("w", newline="", encoding="utf-8-sig") as f:
        writer = csv.DictWriter(
            f,
            fieldnames=[
                "type", "chunk_number", "path", "size_bytes", "sha256",
                "member_count", "relevant_text_member_count"
            ],
        )
        writer.writeheader()
        writer.writerows(rows)

    print(f"SCAN_ROOT={root}")
    print(f"ZIP_COUNT={len(zip_files)}")
    print(f"CHUNK_DIR_COUNT={len(chunk_dirs)}")
    print(f"OBSERVED_CHUNKS={all_numbers}")
    print(f"NUMBERING_GAPS={gaps if gaps else 'NONE'}")
    print(f"EXACT_DUPLICATE_GROUPS={len(exact_dupes)}")
    print(f"REPORT_READY={report}")
    print(f"MANIFEST_READY={manifest}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
'''

